# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KESİR, ONDALIK VE YÜZDE GÖSTERİMLERİ ARASINDA DÖNÜŞÜM</text>\n  <rect x="35" y="55" width="200" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kesir Gösterimi</text>\n  <text x="135" y="110" text-anchor="middle" font-size="12" fill="#334155">• 1/2 (Yarım) • 1/4 (Çeyrek)</text>\n  <text x="135" y="135" text-anchor="middle" font-size="12" fill="#334155">• 3/4 (Dörtte üç)</text>\n  <text x="135" y="160" text-anchor="middle" font-size="12" fill="#334155">• 1/5 (Beşte bir)</text>\n  <text x="135" y="185" text-anchor="middle" font-size="12" fill="#334155">• 3/8 (Sekizde üç)</text>\n  <text x="135" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Payda 10, 100, 1000 yapılır!</text>\n  <rect x="250" y="55" width="200" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ondalık Gösterim</text>\n  <text x="350" y="110" text-anchor="middle" font-size="12" fill="#334155">• 1/2 = 0,5 • 1/4 = 0,25</text>\n  <text x="350" y="135" text-anchor="middle" font-size="12" fill="#334155">• 3/4 = 0,75</text>\n  <text x="350" y="160" text-anchor="middle" font-size="12" fill="#334155">• 1/5 = 0,2</text>\n  <text x="350" y="185" text-anchor="middle" font-size="12" fill="#334155">• 3/8 = 0,375</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Virgüller alt alta hizalanır!</text>\n  <rect x="465" y="55" width="200" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="565" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Yüzde Gösterimi (%)</text>\n  <text x="565" y="110" text-anchor="middle" font-size="12" fill="#334155">• 1/2 = 50/100 = %50</text>\n  <text x="565" y="135" text-anchor="middle" font-size="12" fill="#334155">• 1/4 = 25/100 = %25</text>\n  <text x="565" y="160" text-anchor="middle" font-size="12" fill="#334155">• 3/4 = 75/100 = %75</text>\n  <text x="565" y="185" text-anchor="middle" font-size="12" fill="#334155">• 1/5 = 20/100 = %20</text>\n  <text x="565" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">İndirim ve zam hesabında!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KESİR VE ONDALIK PROBLEMLERİNDE MODELLEME STRATEJİLERİ</text>\n  <rect x="40" y="55" width="300" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="190" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bütünden Parçaya ve Kalanın Kesri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Bir bütünün kesir kadarı: Bütün × Kesir</text>\n  <text x="55" y="130" font-size="11" fill="#475569">Örnek: 240 TL\'nin 3/8\'i → (240 ÷ 8) × 3 = 90 TL</text>\n  <text x="55" y="158" font-size="11.5" fill="#334155">• Parçadan bütüne: Verilen sayı ÷ Kesir</text>\n  <text x="55" y="180" font-size="11" fill="#475569">Örnek: 2/5\'i 60 olan sayı → (60 ÷ 2) × 5 = 150</text>\n  <text x="190" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Şerit model (kesir kutuları) çizmek çözümü kolaylaştırır!</text>\n  <rect x="360" y="55" width="300" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="510" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ondalık ve Yüzde ile Dört İşlem</text>\n  <text x="375" y="108" font-size="11.5" fill="#334155">• Toplama/Çıkarma: Virgüller alt alta gelir,</text>\n  <text x="385" y="126" font-size="11" fill="#475569">eksik basamaklara sağdan 0 eklenir.</text>\n  <text x="375" y="152" font-size="11.5" fill="#334155">• Çarpma: Virgül yokmuş gibi çarpılır, toplam</text>\n  <text x="385" y="170" font-size="11" fill="#475569">ondalık basamak sayısı kadar sola kayılır.</text>\n  <text x="375" y="196" font-size="11.5" fill="#334155">• Bölme: Bölen doğal sayı olacak şekilde</text>\n  <text x="385" y="214" font-size="11" fill="#475569">10, 100 ile genişletilir (12,6 ÷ 0,3 = 126 ÷ 3 = 42).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">POLYA\'NIN PROBLEM ÇÖZME ADIMLARI VE GERÇEK YAŞAM UYGULAMASI</text>\n  <rect x="25" y="65" width="150" height="155" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="100" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Problemi Anla</text>\n  <text x="100" y="118" text-anchor="middle" font-size="11" fill="#334155">Verilen nicelikleri</text>\n  <text x="100" y="136" text-anchor="middle" font-size="11" fill="#334155">(kesir, ondalık, %)</text>\n  <text x="100" y="154" text-anchor="middle" font-size="11" fill="#334155">ve istenen hedefi</text>\n  <text x="100" y="172" text-anchor="middle" font-size="11" fill="#334155">kendi cümlenle yaz.</text>\n  <rect x="192" y="65" width="150" height="155" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="267" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Strateji Seç</text>\n  <text x="267" y="118" text-anchor="middle" font-size="11" fill="#334155">Şekil/diyagram çiz,</text>\n  <text x="267" y="136" text-anchor="middle" font-size="11" fill="#334155">tüm sayıları aynı</text>\n  <text x="267" y="154" text-anchor="middle" font-size="11" fill="#334155">gösterime çevir ve</text>\n  <text x="267" y="172" text-anchor="middle" font-size="11" fill="#334155">sonucu tahmin et.</text>\n  <rect x="359" y="65" width="150" height="155" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="434" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Planı Uygula</text>\n  <text x="434" y="118" text-anchor="middle" font-size="11" fill="#334155">Belirlenen işlem</text>\n  <text x="434" y="136" text-anchor="middle" font-size="11" fill="#334155">önceliğine göre</text>\n  <text x="434" y="154" text-anchor="middle" font-size="11" fill="#334155">dört işlemleri adım</text>\n  <text x="434" y="172" text-anchor="middle" font-size="11" fill="#334155">adım gerçekleştir.</text>\n  <rect x="526" y="65" width="150" height="155" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="601" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">4. Kontrol &amp; Genelle</text>\n  <text x="601" y="118" text-anchor="middle" font-size="11" fill="#334155">Bulunan sonucu</text>\n  <text x="601" y="136" text-anchor="middle" font-size="11" fill="#334155">tahminle kıyasla,</text>\n  <text x="601" y="154" text-anchor="middle" font-size="11" fill="#334155">kısa yolları bul ve</text>\n  <text x="601" y="172" text-anchor="middle" font-size="11" fill="#334155">yeni duruma genelle.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
